<?php namespace App\Models; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\HasMany;
class Client extends Model { use HasFactory; protected $fillable = ["name","short_code","name_display_format","color","phone_dispo","phone_backup","email_dispo","email_wagenliste","email_schadwagen","notes"];
public function getDisplayNameAttribute(): string { return match($this->name_display_format) { "short" => $this->short_code, "name" => $this->name, default => "[{$this->short_code}] {$this->name}" }; } public function appointments(): HasMany { return $this->hasMany(Appointment::class); } }
